fizzbuzz.code:
for {set i 1} {$i <= 15} {incr i} {
    if {$i % 15 == 0} {
        puts FizzBuzz
    } elseif {$i % 3 == 0} {
        puts Fizz
    } elseif {$i % 5 == 0} {
        puts Buzz
    } else {
        puts $i
    }
}

higher-order.code:
# lmap maps a body over a list; continue drops the element.
set squares [lmap x [lseq 1 10] {
    if {$x % 2} continue
    expr {$x * $x}
}]
puts $squares

shapes.code:
oo::class create Rectangle {
    variable width height
    constructor {w h} {
        set width $w
        set height $h
    }
    method area {} { expr {$width * $height} }
}

oo::class create Triangle {
    variable base height
    constructor {b h} {
        set base $b
        set height $h
    }
    method area {} { expr {$base * $height / 2} }
}

# Each object is a new command: [$shape area] calls its area method.
foreach shape [list [Rectangle new 3 4] [Triangle new 10 3]] {
    set class [namespace tail [info object class $shape]]
    puts "$class: [$shape area]"
}

signature.code:
# Every statement is a command, even if and while, so you can write your own:
# the body arrives as an unevaluated string and runs in the caller's frame.
proc unless {cond body} {
    if {![uplevel 1 [list expr $cond]]} { uplevel 1 $body }
}
# upvar binds a local name to a variable of the caller (call by name).
proc swap {aName bName} {
    upvar 1 $aName a $bName b
    lassign [list $b $a] a b
}
set x 1; set y 2
swap x y
unless {$x < $y} { puts "swapped: x=$x y=$y" }

# Everything is a string: one value read as text, as a list, and as code.
set v {3 4 5}
puts "[string length $v] chars, [llength $v] items, sum [expr [join $v +]]"

# A lambda is a two-element list: apply calls it, lmap maps it over a list.
puts [lmap w {tcl is fun} {apply {s {string toupper $s}} $w}]
puts "unless takes {[info args unless]}"
